create table if not exists public.staff_members(user_id uuid primary key references auth.users(id) on delete cascade, role text not null check(role in ('super_admin','admin','marketing_manager','sales_manager','content_editor')), is_active boolean not null default true, created_at timestamptz not null default now());
create or replace function public.is_nexora_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.staff_members where user_id=auth.uid() and is_active) $$;
create or replace function public.has_nexora_role(allowed_roles text[]) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.staff_members where user_id=auth.uid() and is_active and role=any(allowed_roles)) $$;
alter table public.products add column if not exists target_market text, add column if not exists benefits text[] not null default '{}', add column if not exists technology_stack text[] not null default '{}', add column if not exists seo_title text, add column if not exists seo_description text, add column if not exists demo_enabled boolean not null default false, add column if not exists default_demo_minutes integer not null default 7 check(default_demo_minutes between 5 and 10);
create table if not exists public.product_integrations(id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, integration_type text not null check(integration_type in ('direct_url','iframe','api','sso')), application_url text, health_status text not null default 'unknown' check(health_status in ('unknown','healthy','degraded','offline')), last_checked_at timestamptz, configuration jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists public.demo_policies(id uuid primary key default gen_random_uuid(), product_id uuid not null unique references public.products(id) on delete cascade, enabled boolean not null default false, duration_minutes integer not null default 7 check(duration_minutes between 5 and 10), idle_timeout_seconds integer not null default 90 check(idle_timeout_seconds between 30 and 600), max_active_sessions integer not null default 1, watermark_text text not null default 'DEMO VERSION · NEXORA DIGITAL', allow_renewal boolean not null default false);
create table if not exists public.demo_sessions(id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, session_token_hash text not null unique, visitor_hash text not null, status text not null default 'active' check(status in ('active','expired','ended','revoked')), started_at timestamptz not null default now(), last_seen_at timestamptz not null default now(), expires_at timestamptz not null, ended_at timestamptz, metadata jsonb not null default '{}');
create table if not exists public.leads(id uuid primary key default gen_random_uuid(), full_name text not null check(char_length(full_name) between 2 and 120), email text not null, phone text, company text, industry text, product_id uuid references public.products(id) on delete set null, source text not null default 'website', need_description text, status text not null default 'new' check(status in ('new','contacted','qualified','negotiation','proposal_sent','won','lost')), consent_marketing boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.lead_activities(id uuid primary key default gen_random_uuid(), lead_id uuid not null references public.leads(id) on delete cascade, activity_type text not null, notes text, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now());
create table if not exists public.sales_inquiries(id uuid primary key default gen_random_uuid(), lead_id uuid references public.leads(id) on delete set null, product_id uuid references public.products(id) on delete set null, inquiry_type text not null check(inquiry_type in ('quotation','consultation','custom_development','license','partnership')), message text not null, budget_range text, timeline text, status text not null default 'new', created_at timestamptz not null default now());
create table if not exists public.pricing_packages(id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, name text not null, description text, billing_period text not null default 'custom', price_amount numeric(14,2), currency text not null default 'IDR', features jsonb not null default '[]', is_public boolean not null default false, sort_order integer not null default 0);
create table if not exists public.subscriptions(id uuid primary key default gen_random_uuid(), lead_id uuid references public.leads(id) on delete set null, pricing_package_id uuid references public.pricing_packages(id) on delete set null, status text not null default 'inquiry', starts_at timestamptz, ends_at timestamptz, external_reference text, created_at timestamptz not null default now());
create table if not exists public.licenses(id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id), lead_id uuid references public.leads(id), license_type text not null, status text not null default 'pending', issued_at timestamptz, expires_at timestamptz, metadata jsonb not null default '{}');
create table if not exists public.content_projects(id uuid primary key default gen_random_uuid(), product_id uuid references public.products(id), title text not null, content_type text not null, objective text, status text not null default 'draft', brief jsonb not null default '{}', created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table if not exists public.content_assets(id uuid primary key default gen_random_uuid(), content_project_id uuid references public.content_projects(id) on delete cascade, product_id uuid references public.products(id), asset_type text not null, storage_path text, mime_type text, file_size_bytes bigint, title text, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists public.content_templates(id uuid primary key default gen_random_uuid(), name text not null, content_type text not null, dimensions jsonb not null default '{}', template_data jsonb not null default '{}', is_active boolean not null default true);
create table if not exists public.content_calendar(id uuid primary key default gen_random_uuid(), content_project_id uuid references public.content_projects(id), product_id uuid references public.products(id), channel text not null, scheduled_at timestamptz, status text not null default 'planned', caption text);
create table if not exists public.ai_recommendations(id uuid primary key default gen_random_uuid(), product_id uuid references public.products(id), recommendation_type text not null, title text not null, description text not null, evidence jsonb not null default '{}', confidence numeric(5,2), status text not null default 'new', created_at timestamptz not null default now());
create table if not exists public.analytics_events(id uuid primary key default gen_random_uuid(), event_name text not null, product_id uuid references public.products(id), session_hash text, source text, path text, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists public.testimonials(id uuid primary key default gen_random_uuid(), product_id uuid references public.products(id), customer_name text not null, company text, quote text not null, rating integer, is_published boolean not null default false);
create table if not exists public.articles(id uuid primary key default gen_random_uuid(), title text not null, slug text not null unique, excerpt text, body text, cover_path text, status text not null default 'draft', published_at timestamptz, seo_title text, seo_description text, created_at timestamptz not null default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, entity_type text, entity_id uuid, metadata jsonb not null default '{}', created_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['staff_members','product_integrations','demo_policies','demo_sessions','leads','lead_activities','sales_inquiries','pricing_packages','subscriptions','licenses','content_projects','content_assets','content_templates','content_calendar','ai_recommendations','analytics_events','testimonials','articles','audit_logs'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy "Staff read staff" on public.staff_members for select to authenticated using(public.is_nexora_staff());
create policy "Super admins manage staff" on public.staff_members for all to authenticated using(public.has_nexora_role(array['super_admin'])) with check(public.has_nexora_role(array['super_admin']));
create policy "Staff manage integrations" on public.product_integrations for all to authenticated using(public.is_nexora_staff()) with check(public.is_nexora_staff());
create policy "Staff manage demo policies" on public.demo_policies for all to authenticated using(public.is_nexora_staff()) with check(public.is_nexora_staff());
create policy "Staff manage leads" on public.leads for all to authenticated using(public.is_nexora_staff()) with check(public.is_nexora_staff());
create policy "Public submit leads" on public.leads for insert to anon,authenticated with check(status='new');
create policy "Staff manage lead activities" on public.lead_activities for all to authenticated using(public.is_nexora_staff()) with check(public.is_nexora_staff());
create policy "Staff manage inquiries" on public.sales_inquiries for all to authenticated using(public.is_nexora_staff()) with check(public.is_nexora_staff());
create policy "Public submit inquiries" on public.sales_inquiries for insert to anon,authenticated with check(status='new');
create policy "Staff manage pricing" on public.pricing_packages for all to authenticated using(public.is_nexora_staff()) with check(public.is_nexora_staff());
create policy "Public read pricing" on public.pricing_packages for select to anon,authenticated using(is_public);
create policy "Staff manage subscriptions" on public.subscriptions for all to authenticated using(public.is_nexora_staff()) with check(public.is_nexora_staff());
create policy "Staff manage licenses" on public.licenses for all to authenticated using(public.is_nexora_staff()) with check(public.is_nexora_staff());
create policy "Staff manage content projects" on public.content_projects for all to authenticated using(public.is_nexora_staff()) with check(public.is_nexora_staff());
create policy "Staff manage content assets" on public.content_assets for all to authenticated using(public.is_nexora_staff()) with check(public.is_nexora_staff());
create policy "Staff manage templates" on public.content_templates for all to authenticated using(public.is_nexora_staff()) with check(public.is_nexora_staff());
create policy "Staff manage calendar" on public.content_calendar for all to authenticated using(public.is_nexora_staff()) with check(public.is_nexora_staff());
create policy "Staff manage recommendations" on public.ai_recommendations for all to authenticated using(public.is_nexora_staff()) with check(public.is_nexora_staff());
create policy "Public insert analytics" on public.analytics_events for insert to anon,authenticated with check(char_length(event_name) between 1 and 80);
create policy "Staff read analytics" on public.analytics_events for select to authenticated using(public.is_nexora_staff());
create policy "Staff manage testimonials" on public.testimonials for all to authenticated using(public.is_nexora_staff()) with check(public.is_nexora_staff());
create policy "Public read testimonials" on public.testimonials for select to anon,authenticated using(is_published);
create policy "Staff manage articles" on public.articles for all to authenticated using(public.is_nexora_staff()) with check(public.is_nexora_staff());
create policy "Public read articles" on public.articles for select to anon,authenticated using(status='published');
create policy "Staff read audit logs" on public.audit_logs for select to authenticated using(public.is_nexora_staff());
grant select on public.product_categories,public.products,public.product_features,public.product_media,public.pricing_packages,public.testimonials,public.articles to anon,authenticated;
grant insert on public.leads,public.sales_inquiries,public.analytics_events to anon,authenticated;
grant all on all tables in schema public to authenticated;
